    private static NativeWirelessRedstoneBlockEntity endpoint(BlockPos pos,boolean tx,Direction port){world.getChunkAt(pos);var block=tx?VandorLabsBootstrap.REDSTONE_TRANSMITTER_BLOCK.get():VandorLabsBootstrap.REDSTONE_RECEIVER_BLOCK.get();world.setBlock(pos,block.defaultBlockState().setValue(NativeWirelessRedstoneBlock.FACING,port),2);var tile=(NativeWirelessRedstoneBlockEntity)world.getBlockEntity(pos);tile.onLoad();NativeRedstoneChannels.flush(world);return tile;}
