    private static void matrix(){
        for(Direction port:Direction.values())for(boolean conductor:new boolean[]{false,true}){
            var tx=endpoint(TX,true,port);var rx=endpoint(RX,false,port);require(tx.analog()&&!tx.localRedstone()&&tx.transmissionRange()==16&&rx.transmissionRange()==-1,"fresh role-specific defaults");tx.configureTransmission(ChannelList.of(61001,61002),16,true);rx.configure(ChannelList.of(61002,61003),true,8,3,port);var input=TX.relative(port);var sourcePos=conductor?input.relative(port):input;if(conductor)world.setBlock(input,Blocks.STONE.defaultBlockState(),2);var source=source(sourcePos,port,61999);
            for(int value=0;value<=15;value++){
                tx.configure(tx.getRedstoneChannels(),true,15,0,port);rx.configure(ChannelList.of(61002,61003),true,8,3,port);source.applyLinkedLevels(Map.of(61999,value));tx.sampleInput();require(tx.localSignalLevel(61001)==value&&NativeRedstoneChannels.level(world,RX,61002)==value,"loaded selected weak/conductor strong input "+port+"/"+conductor+"/"+value);
                for(Direction side:Direction.values()){int expected=side==port.getOpposite()?(value>0?value:3):0;require(rx.getBlockState().getSignal(world,RX,side)==expected&&rx.getBlockState().getDirectSignal(world,RX,side)==expected,"six-sided receiver analog/output");require(tx.getBlockState().getSignal(world,TX,side)==(side==port?value:0),"transmitter physical side");require(rx.getBlockState().canRedstoneConnectTo(world,RX,side)==(side==port.getOpposite()),"one-sided wire connection");}
                rx.configure(rx.getRedstoneChannels(),false,8,3,port);require(rx.getOutputLevel()==(value>0?8:3),"receiver digital On/Off");tx.configure(tx.getRedstoneChannels(),false,15,0,port);rx.configure(rx.getRedstoneChannels(),true,15,0,port);require(rx.getOutputLevel()==(value>0?15:0),"transmitter digital threshold");
            }
            tx.configureTransmission(ChannelList.of(61001,61002),16,false);require(tx.getBlockState().getSignal(world,TX,port)==0&&rx.getOutputLevel()==15,"Local off retains wireless source");world.removeBlock(sourcePos,false);if(conductor)world.removeBlock(input,false);tx.sampleInput();require(rx.getOutputLevel()==0,"input removal withdraws numeric output");world.removeBlock(TX,false);world.removeBlock(RX,false);
        }
    }
    /** A wireless receiver takes MAX while the same mounted control retains its per-channel MIN bank. */
    private static void mountedInteroperation(){
        BlockPos sliderPos=TX.south(32),rockerPos=sliderPos.south(2),receiverPos=sliderPos.east(4);
        world.getChunkAt(sliderPos);world.setBlock(sliderPos.below(),Blocks.STONE.defaultBlockState(),2);
        world.setBlock(sliderPos,VandorLabsBootstrap.WALL_SLIDER.get().defaultBlockState().setValue(NativeSignalControlBlock.FACING,Direction.UP),2);
        var slider=(NativeSignalControlBlockEntity)world.getBlockEntity(sliderPos);slider.configureTransmission(ChannelList.of(65001,65002),16,false);slider.setStep(1);
        var receiver=endpoint(receiverPos,false,Direction.UP);receiver.configure(ChannelList.of(65001,65002),true,15,0,Direction.UP);
        require(slider.getOutputLevel()==5&&receiver.getOutputLevel()==5,"four-step source reaches wireless receiver");
        world.setBlock(rockerPos.below(),Blocks.STONE.defaultBlockState(),2);var rocker=source(rockerPos,Direction.UP,65001);require(rocker.isLocalOn()&&rocker.latchedLevel(65001)==5,"joining rocker inherits existing numeric latch level");rocker.setLocalOn(false);rocker.setLocalOn(true);
        require(slider.latchedLevel(65001)==15&&slider.latchedLevel(65002)==5&&slider.getOutputLevel()==5&&receiver.getOutputLevel()==15,"wireless MAX differs from partial mounted MIN bank");
        rocker.setLocalOn(false);require(slider.getOutputLevel()==0&&receiver.getOutputLevel()==5,"receiver retains positive unmatched channel after linked toggle OFF");
        world.removeBlock(rockerPos,false);world.removeBlock(sliderPos,false);require(receiver.getOutputLevel()==0,"removing all mounted sources withdraws receiver output");
        world.removeBlock(receiverPos,false);world.removeBlock(sliderPos.below(),false);world.removeBlock(rockerPos.below(),false);
    }
    private static void maximumAndRanges(){
        var first=endpoint(TX,true,Direction.UP);world.setBlock(TX.above(),Blocks.REDSTONE_BLOCK.defaultBlockState(),2);first.sampleInput();first.configureTransmission(ChannelList.of(62001),16,false);var second=endpoint(TX.south(4),true,Direction.UP);var control=source(second.getBlockPos().above(),Direction.UP,62999);control.applyLinkedLevels(Map.of(62999,7));second.sampleInput();second.configureTransmission(ChannelList.of(62002),16,false);var rx=endpoint(RX,false,Direction.UP);rx.configure(ChannelList.of(62001,62002),true,3,2,Direction.UP);require(rx.getOutputLevel()==15,"receiver uses MAX across independent channels, not mounted minimum");world.removeBlock(TX.above(),false);first.sampleInput();require(rx.getOutputLevel()==7,"remaining partial subscription keeps7");
        for(int radius:TransmissionSettings.RANGES){second.configureTransmission(ChannelList.of(62002),radius,false);require(NativeRedstoneChannels.level(world,second.getBlockPos().east(radius),62002)==7&&NativeRedstoneChannels.level(world,second.getBlockPos().offset(radius,1,0),62002)==0,"inclusive finite spherical boundary "+radius);}
        world.removeBlock(second.getBlockPos().above(),false);world.removeBlock(second.getBlockPos(),false);world.removeBlock(TX,false);world.removeBlock(RX,false);
    }
