        int[] maximum=new int[64];for(int i=0;i<maximum.length;i++)maximum[i]=Integer.MAX_VALUE-i;var full=ChannelList.of(maximum);var maxFrame=new RegistryFriendlyByteBuf(Unpooled.buffer(),world.registryAccess());WirelessPayload.CODEC.encode(maxFrame,new WirelessPayload(TX,51,full,true,15,0,Direction.UP));require(maxFrame.readableBytes()==273,"maximum endpoint frame273bytes");var maxDecoded=WirelessPayload.CODEC.decode(maxFrame);require(maxDecoded.receive().size()==64&&maxDecoded.receive().get(63)==Integer.MAX_VALUE,"64 maximum-int channels endpoint roundtrip");maxFrame.release();var maxInline=new RegistryFriendlyByteBuf(Unpooled.buffer(),world.registryAccess());WirelessTransmissionPayload.CODEC.encode(maxInline,new WirelessTransmissionPayload(TX,51,full,256,false));require(maxInline.readableBytes()==272&&WirelessTransmissionPayload.CODEC.decode(maxInline).channels().equals(full),"shared inline max64 channels272bytes");maxInline.release();
        for(int count:new int[]{65,255}){var bad=new RegistryFriendlyByteBuf(Unpooled.buffer(),world.registryAccess());bad.writeBlockPos(TX);bad.writeInt(51);bad.writeBoolean(true);bad.writeByte(15);bad.writeByte(0);bad.writeByte(0);bad.writeByte(count);try{WirelessPayload.CODEC.decode(bad);throw new AssertionError("unbounded endpoint count");}catch(IllegalArgumentException expected){}finally{bad.release();}}
