    private static void reference(){
        String file=System.getProperty("vandorlabs.wirelessLegacyReference","");if(file.isEmpty())return;try{byte[] bytes=Files.readAllBytes(Path.of(file));String hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));require(hash.equals("58e0116470725978516fd253d87a513b6362e1f1ed02ca70d17650cf825d716d"),"frozen Forge reference hash");var root=JsonParser.parseString(new String(bytes,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();int count=0;for(var element:root.getAsJsonArray("cases")){var c=element.getAsJsonObject();var input=TagParser.parseTag(c.get("input").getAsString());var original=input.copy();var tile=new NativeWirelessRedstoneBlockEntity(BlockPos.ZERO,VandorLabsBootstrap.REDSTONE_RECEIVER_BLOCK.get().defaultBlockState());tile.loadWithComponents(input,world.registryAccess());var saved=tile.saveWithFullMetadata(world.registryAccess());require(input.equals(original)&&tile.analog()==c.get("analog").getAsBoolean()&&tile.onLevel()==c.get("on").getAsInt()&&tile.offLevel()==c.get("off").getAsInt()&&tile.getOutputLevel()==c.get("output").getAsInt(),"actual Forge scalar/output "+count);require(saved.getInt("WirelessInput")==c.get("inputLevel").getAsInt()&&saved.getInt("WirelessReceived")==c.get("receivedLevel").getAsInt()&&tile.configuration().equals(TagParser.parseTag(c.get("configuration").getAsString()))&&saved.getCompound("ForgeData").equals(input.getCompound("ForgeData"))&&saved.getCompound("ForgeCaps").equals(input.getCompound("ForgeCaps")),"actual Forge runtime/configuration and retained opaque "+count);count++;}require(count==385,"Forge reference count");System.out.println("[vandorlabs][wireless] Forge-reference PASS cases="+count+" SHA256="+hash);}catch(Exception failure){throw new IllegalStateException("Wireless Forge reference",failure);}
    }
