    @SubscribeEvent public static void start(ServerStartedEvent event){String phase=System.getProperty("vandorlabs.transmitterPhase","");if(!Set.of("wireless-write","wireless-read","wireless-closed-query","wireless-removal-observer","wireless-configurizer").contains(phase))return;world=event.getServer().overworld();checks=0;if(phase.equals("wireless-configurizer")){configurizer();System.out.println("[vandorlabs][wireless] server-wireless-configurizer PASS checks="+checks);event.getServer().halt(false);return;}if(phase.equals("wireless-closed-query")||phase.equals("wireless-removal-observer")){if(phase.equals("wireless-closed-query"))closedQueries();else removalObserver();System.out.println("[vandorlabs][wireless] server-"+phase+" PASS checks="+checks);event.getServer().halt(false);return;}if(phase.equals("wireless-write")){reference();matrix();maximumAndRanges();mountedInteroperation();sessions();unloadedInput();var tx=endpoint(TX,true,Direction.UP);world.setBlock(TX.above(),Blocks.REDSTONE_BLOCK.defaultBlockState(),2);tx.sampleInput();tx.configureTransmission(ChannelList.of(64001),16,false);var rx=endpoint(RX,false,Direction.DOWN);rx.configure(ChannelList.of(64001),false,9,2,Direction.DOWN);var tag=rx.saveWithFullMetadata(world.registryAccess());var opaque=new CompoundTag();opaque.putString("opaque","retain");tag.put("ForgeCaps",opaque);rx.loadWithComponents(tag,world.registryAccess());NativeRedstoneChannels.flush(world);require(rx.getOutputLevel()==9&&tag.getString("id").equals("vandorlabs:wireless_redstone"),"saved pair and retained BE id");ticks=0;idle=true;}else{world.getChunkAt(TX);world.getChunkAt(RX);NativeRedstoneChannels.flush(world);var tx=(NativeWirelessRedstoneBlockEntity)world.getBlockEntity(TX);var rx=(NativeWirelessRedstoneBlockEntity)world.getBlockEntity(RX);require(tx.transmissionChannels().equals(ChannelList.of(64001))&&!tx.localRedstone()&&rx.getOutputLevel()==9&&rx.port()==Direction.DOWN,"second JVM pair/settings/port/source restore");require(rx.saveWithFullMetadata(world.registryAccess()).getCompound("ForgeCaps").getString("opaque").equals("retain"),"second JVM opaque capability retention");System.out.println("[vandorlabs][wireless] server-wireless-read PASS checks="+checks);event.getServer().halt(false);}}
    @SubscribeEvent public static void tick(ServerTickEvent.Post event){if(!idle)return;if(++ticks==20)baseline=NativeRedstoneChannels.diagnostics(world);if(ticks==120){require(Arrays.equals(baseline,NativeRedstoneChannels.diagnostics(world)),"actual100idle ticks do not rescan/retransmit");idle=false;lifetime();System.out.println("[vandorlabs][wireless] server-wireless-write PASS checks="+checks);event.getServer().halt(false);}}
